#include "PluginProcessor.h"
#include "PluginEditor.h"
#include <chrono>
#include <iostream>
#include <numeric>
int main(){juce::ScopedJuceInitialiser_GUI gui;constexpr double rate=48000;constexpr int block=256,iterations=700;juce::Array<juce::var> cases;
 struct Scenario{const char* name;int engine,voices,effect,master;};
 for(auto scenario:{Scenario{"idle",0,0,0,0},{"voltage-8",0,8,0,0},{"dimension-8",5,8,0,0},{"dna-8",9,8,0,0},{"sampler-8",11,8,0,0},{"vocoder-4",12,4,0,0},{"cwo-mother-8",1,8,7,9}}){auto p=std::make_unique<FieldProcessor>();p->prepareToPlay(rate,block);p->setValue("engine",(float)scenario.engine);p->setValue("effect",(float)scenario.effect);p->setValue("masterEffect",(float)scenario.master);p->setValue("sustain",.8f);p->setValue("effectMix",1);p->setValue("masterMix",1);if(scenario.engine==11){std::vector<float> sample(48000);for(size_t i=0;i<sample.size();++i)sample[i]=.2f*std::sin(i*.1f);p->engine.loadSample(sample,sample,rate);p->setValue("sampleLoop",1);}juce::AudioBuffer<float> audio(2,block);juce::MidiBuffer midi;midi.ensureSize(65536);double sum=0,maximum=0,checksum=0;for(int i=-100;i<iterations;++i){for(int n=0;n<block;++n){audio.setSample(0,n,.1f*std::sin((i*block+n)*.05f));audio.setSample(1,n,.1f*std::sin((i*block+n)*.07f));}midi.clear();if(i==-100)for(int voice=0;voice<scenario.voices;++voice)midi.addEvent(juce::MidiMessage::noteOn(1,48+voice*2,.8f),0);auto start=std::chrono::steady_clock::now();p->processBlock(audio,midi);double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(i>=0){sum+=seconds;maximum=std::max(maximum,seconds);checksum+=audio.getSample(0,127);}}auto* result=new juce::DynamicObject;result->setProperty("scenario",scenario.name);result->setProperty("mean_callback_us",sum/iterations*1e6);result->setProperty("peak_callback_us",maximum*1e6);result->setProperty("mean_deadline_percent",sum/iterations/(block/rate)*100);result->setProperty("checksum",checksum);cases.add(juce::var(result));}
 juce::Array<juce::var> painting;{auto processor=std::make_unique<FieldProcessor>();processor->prepareToPlay(rate,block);std::unique_ptr<juce::AudioProcessorEditor> editor(processor->createEditor());for(bool full:{true,false}){double sum=0;for(int frame=0;frame<40;++frame){auto start=std::chrono::steady_clock::now();auto image=editor->createComponentSnapshot(full?editor->getLocalBounds():juce::Rectangle<int>((int)(editor->getWidth()*.24),(int)(editor->getHeight()*.2),300,150));sum+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}auto* row=new juce::DynamicObject;row->setProperty("region",full?"full-editor":"lcd-sized-region");row->setProperty("mean_redraw_ms",sum/40*1000);painting.add(juce::var(row));}}
 auto* output=new juce::DynamicObject;output->setProperty("sample_rate",rate);output->setProperty("block_frames",block);output->setProperty("cases",cases);output->setProperty("offscreen_paint",painting);std::cout<<juce::JSON::toString(juce::var(output),false)<<'\n';}
